#!/usr/bin/python3
"""Row 0 is not moved back from past the right margin.

pyte 0.8.0 insert_characters writes one cell past the last column, and
delete_characters pulls that cell back onto the row. On this scenario the
cell is phases 2 and 3, row 0, column 10: pyte keeps k and the terminal
leaves a space. Every other cell, cursor, size and reply still has to match.
"""
import json
import sys
from pathlib import Path

ALLOWED = {(2, 0, 10), (3, 0, 10)}
HOME = Path("/tmp/parity-home")


def load(path):
    return json.loads(Path(path).read_text())


def dump(path, data):
    Path(path).write_text(
        json.dumps(data, sort_keys=True, ensure_ascii=False, indent=2) + "\n")


def cell_diff(result, oracle):
    if len(result) != len(oracle):
        raise SystemExit("phase count differs")
    seen = set()
    for phase, (got, want) in enumerate(zip(result, oracle)):
        for key in ("size", "cursor", "responses_base64"):
            if got.get(key) != want.get(key):
                raise SystemExit("phase %d %s differs" % (phase, key))
        got_rows, want_rows = got["cells"], want["cells"]
        if len(got_rows) != len(want_rows):
            raise SystemExit("phase %d row count" % phase)
        for y, (got_row, want_row) in enumerate(zip(got_rows, want_rows)):
            if len(got_row) != len(want_row):
                raise SystemExit("phase %d width" % phase)
            for x, (got_cell, want_cell) in enumerate(zip(got_row, want_row)):
                if got_cell == want_cell:
                    continue
                if (phase, y, x) not in ALLOWED:
                    raise SystemExit("unexpected cell %d %d %d" % (phase, y, x))
                if got_cell.get("text") != " " or want_cell.get("text") != "k":
                    raise SystemExit("disputed cell is not a space against pyte k")
                rest_got = dict(got_cell)
                rest_want = dict(want_cell)
                rest_got.pop("text", None)
                rest_want.pop("text", None)
                if rest_got != rest_want:
                    raise SystemExit("disputed cell attributes differ")
                seen.add((phase, y, x))
    return seen


def main():
    mode = sys.argv[1]
    if mode == "reference":
        result = load("result.json")
        for phase, row, col in sorted(ALLOWED):
            cell = result[phase]["cells"][row][col]
            if cell.get("text") != "k":
                raise SystemExit("pyte cell is not k")
            cell["text"] = " "
        dump("result.json", result)
        print("all-explicit-assertions=PASS")
        return
    if mode != "candidate":
        raise SystemExit("mode")
    rc = int(sys.argv[2])
    result = load("result.json")
    oracle = load(HOME / "oracle.json")
    assertions = load(HOME / "assertions.json")
    for row in assertions:
        label = row["label"]
        if label.startswith("rendered-grid-and-each-cell-attributes/phase"):
            phase = int(label.rsplit("phase", 1)[1])
            if phase in (2, 3):
                continue
        if not row["passed"]:
            raise SystemExit("unrelated assertion failed: " + label)
    seen = cell_diff(result, oracle)
    if seen != ALLOWED:
        raise SystemExit("row 0 column 10 was not the only difference")
    if rc == 0:
        raise SystemExit("candidate matched pyte and moved row 0 back onto the margin")
    print("all-explicit-assertions=PASS")


if __name__ == "__main__":
    main()
